      if (primesInRange.length < 1 || compositesInRange.length < 4) return null;
      const correctNum = pick(primesInRange);
      const decoys = shuffle(compositesInRange).slice(0, 4);
      const arr = shuffle([correctNum, ...decoys]);
      const correctIndex = arr.indexOf(correctNum);
