const PCG_ITEM_NAMES = ['A jacket', 'A bicycle', 'A games console', 'A laptop', 'A holiday', 'A sofa', 'A television', 'A phone contract'];

function PCG_dedupeByRoundedCents(correct, candidates) {
  const seen = new Set([Math.round(correct * 100)]);
  const uniq = [];
  for (const c of candidates) {
    if (!Number.isFinite(c) || c < 0) continue;
    const key = Math.round(c * 100);
    if (seen.has(key)) continue;
    seen.add(key);
    uniq.push(c);
  }
  return uniq;
}

