const s1_percentage_of_amount = {
  difficulties: [1],
  build(d) {
    const pctList = [10, 20, 25, 5, 15, 30, 40, 60, 70, 75, 80, 90];
    const pct = pick(pctList);
    const base = rand(1, 20) * 100;
    const answer = base * pct / 100;
    if (!Number.isFinite(answer) || answer <= 0) return null;
    const item = pick(PCG_ITEM_NAMES);
    const q = `${item} costs £${base}. What is ${pct}% of £${base}?`;
    const wrongUsingComplement = base * (100 - pct) / 100;
    const wrongHalf = answer / 2;
    const wrongDouble = answer * 2;
    const wrongDecimalSlip = base * pct / 10;
    const uniq = PCG_dedupeByRoundedCents(answer, [wrongUsingComplement, wrongHalf, wrongDouble, wrongDecimalSlip]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(answer, uniq.slice(0, 4), PCG_fmtMoney);
    return {
      q,
      options,
      correctIndex,
      hint: 'Use the multiplier method: to find a percentage of an amount, multiply by (percentage ÷ 100).',
      solution: {
        idea: `${pct}% means ${pct}/100, so multiply the amount by ${pct}/100.`,
        steps: [
          `£${base} × ${pct}/100`,
          `= £${base} × ${pct / 100}`,
          `= £${answer.toFixed(2)}`,
        ],
        check: `£${answer.toFixed(2)} is ${pct}% of £${base}.`,
      },
    };
  },
};

const s2_percentage_change_multiplier = {
  difficulties: [1],
  build(d) {
    const pctList = [5, 10, 15, 20, 25, 30, 40, 50];
    const pct = pick(pctList);
    const direction = pick(['increase', 'decrease']);
    const original = rand(1, 20) * 20;
    const multiplier = direction === 'increase' ? 1 + pct / 100 : 1 - pct / 100;
    const answer = original * multiplier;
    if (!Number.isFinite(answer) || answer <= 0) return null;
    const rounded = Math.round(answer * 100) / 100;
    const verb = direction === 'increase' ? 'increases' : 'decreases';
    const q = `A price of £${original} ${verb} by ${pct}%. What is the new price?`;
    const wrongAddedPctAsPounds = direction === 'increase' ? original + pct : original - pct;
    const wrongOppositeDirection = direction === 'increase' ? original * (1 - pct / 100) : original * (1 + pct / 100);
    const wrongFindsChangeOnly = original * pct / 100;
    const wrongDoublePct = direction === 'increase' ? original * (1 + 2 * pct / 100) : original * (1 - 2 * pct / 100);
    const uniq = PCG_dedupeByRoundedCents(rounded, [wrongAddedPctAsPounds, wrongOppositeDirection, wrongFindsChangeOnly, wrongDoublePct]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(rounded, uniq.slice(0, 4), PCG_fmtMoney);
    return {
      q,
      options,
      correctIndex,
      hint: `Use the multiplier method: an ${direction} of ${pct}% means multiplying by ${direction === 'increase' ? `1 + ${pct}/100` : `1 − ${pct}/100`}.`,
      solution: {
        idea: `A ${pct}% ${direction} corresponds to a multiplier of ${multiplier}.`,
        steps: [
          `Multiplier = ${direction === 'increase' ? `1 + ${pct}/100` : `1 − ${pct}/100`} = ${multiplier}`,
          `New price = £${original} × ${multiplier}`,
          `= £${rounded.toFixed(2)}`,
        ],
        check: `The new price is £${rounded.toFixed(2)}.`,
      },
    };
  },
};

const s3_compound_interest_forward = {
  difficulties: [1],
  build(d) {
    const principal = rand(2, 20) * 100;
    const rate = pick([2, 3, 4, 5, 6, 8, 10]);
    const years = rand(2, 3);
    const amount = principal * Math.pow(1 + rate / 100, years);
    const rounded = Math.round(amount * 100) / 100;
    if (!Number.isFinite(rounded)) return null;
    const q = `£${principal} is invested at ${rate}% compound interest per year. What is the value of the investment after ${years} years?`;
    const wrongSimple = principal + principal * rate * years / 100;
    const wrongOneYear = principal * (1 + rate / 100);
    const wrongRateAsWhole = principal * Math.pow(1 + rate, years);
    const wrongYearsOff = principal * Math.pow(1 + rate / 100, years + 1);
    const uniq = PCG_dedupeByRoundedCents(rounded, [wrongSimple, wrongOneYear, wrongRateAsWhole, wrongYearsOff]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(rounded, uniq.slice(0, 4), PCG_fmtMoney);
    return {
      q,
      options,
      correctIndex,
      hint: 'Multiply by the same multiplier once for each year (raise the multiplier to the power of the number of years).',
      solution: {
        idea: `Each year the amount is multiplied by ${1 + rate / 100}.`,
        steps: [
          `Multiplier per year = 1 + ${rate}/100 = ${1 + rate / 100}`,
          `Amount = £${principal} × ${1 + rate / 100}^${years}`,
          `= £${rounded.toFixed(2)}`,
        ],
        check: `After ${years} years the investment is worth £${rounded.toFixed(2)}.`,
      },
    };
  },
};

const s4_compound_depreciation_forward = {
  difficulties: [1],
  build(d) {
    const principal = rand(2, 20) * 100;
    const rate = pick([5, 10, 15, 20, 25]);
    const years = rand(2, 3);
    const amount = principal * Math.pow(1 - rate / 100, years);
    const rounded = Math.round(amount * 100) / 100;
    if (!Number.isFinite(rounded) || rounded <= 0) return null;
    const q = `A machine worth £${principal} depreciates by ${rate}% per year (compound depreciation). What is its value after ${years} years?`;
    const wrongSimple = principal - principal * rate * years / 100;
    const wrongOneYear = principal * (1 - rate / 100);
    const wrongRateAsWhole = principal * Math.pow(Math.max(0.01, 1 - rate), years);
    const wrongYearsOff = principal * Math.pow(1 - rate / 100, years + 1);
    const uniq = PCG_dedupeByRoundedCents(rounded, [wrongSimple, wrongOneYear, wrongRateAsWhole, wrongYearsOff]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(rounded, uniq.slice(0, 4), PCG_fmtMoney);
    return {
      q,
      options,
      correctIndex,
      hint: 'Multiply by the same multiplier (less than 1) once for each year.',
      solution: {
        idea: `Each year the value is multiplied by ${1 - rate / 100}.`,
        steps: [
          `Multiplier per year = 1 − ${rate}/100 = ${1 - rate / 100}`,
          `Value = £${principal} × ${1 - rate / 100}^${years}`,
          `= £${rounded.toFixed(2)}`,
        ],
        check: `After ${years} years the machine is worth £${rounded.toFixed(2)}.`,
      },
    };
  },
};

const s5_percent_decimal_fraction_conversion = {
  difficulties: [1],
  build(d) {
    const entry = pick(PCG_PCT_FAMILY);
    const direction = pick(['pctToDec', 'decToPct', 'pctToFrac']);
    const pctStr = String(entry.pct);
    let q, correct, distractors, idea, steps;
    if (direction === 'pctToDec') {
      q = `Write ${pctStr}% as a decimal.`;
      correct = entry.dec;
      distractors = [pctStr, String(entry.pct / 10), String(entry.pct * 10), String(Math.round((parseFloat(entry.dec) + 0.1) * 1000) / 1000)];
      idea = `${pctStr}% = ${pctStr}/100`;
      steps = [`${pctStr}% = ${pctStr} ÷ 100 = ${entry.dec}`];
    } else if (direction === 'decToPct') {
      q = `Write ${entry.dec} as a percentage.`;
      correct = `${pctStr}%`;
      distractors = [`${entry.dec}%`, `${Math.round((parseFloat(entry.dec) / 10) * 1000) / 1000}%`, `${parseFloat(entry.dec) * 1000}%`, `${entry.pct + 10}%`];
      idea = `${entry.dec} × 100 = ${pctStr}%`;
      steps = [`${entry.dec} × 100 = ${pctStr}%`];
    } else {
      q = `Write ${pctStr}% as a fraction in its simplest form.`;
      correct = entry.frac;
      const [n, dn] = entry.frac.split('/').map(Number);
      distractors = [`${entry.pct}/100`, `${dn}/${n}`, `${n}/${dn + 10}`, `${n + 1}/${dn}`];
      idea = `${pctStr}% = ${entry.pct}/100, simplified`;
      steps = [`${pctStr}% = ${entry.pct}/100`, `Simplify to ${entry.frac}`];
    }
    const seen = new Set([correct]);
    const uniq = [];
    for (const dtr of distractors) {
      if (seen.has(dtr)) continue;
      seen.add(dtr);
      uniq.push(dtr);
    }
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMCStr(correct, uniq.slice(0, 4));
    return {
      q,
      options,
      correctIndex,
      hint: 'Percentage means "out of 100": divide by 100 for a decimal, or write over 100 and simplify for a fraction.',
      solution: {
        idea,
        steps,
        check: `${pctStr}% = ${entry.dec} = ${entry.frac}`,
      },
    };
  },
};

