const s6_reverse_percentage_single = {
  difficulties: [2],
  build(d) {
    const e = pick(PCG_CHANGE_FRACTIONS);
    const k = rand(2, 20);
    const original = e.den * k;
    const final = e.num * k;
    if (final <= 0 || original <= 0) return null;
    const direction = e.sign === 1 ? 'increased' : 'decreased';
    const q = `After a price is ${direction} by ${e.pct}%, it becomes £${final}. What was the original price?`;
    const wrongApplyForward = e.sign === 1 ? final * (1 + e.pct / 100) : final * (1 - e.pct / 100);
    const wrongApplyOpposite = e.sign === 1 ? final * (1 - e.pct / 100) : final * (1 + e.pct / 100);
    const wrongThinksNoChange = final;
    const wrongTreatsPctAsPounds = e.sign === 1 ? final - e.pct : final + e.pct;
    const uniq = PCG_dedupeByRoundedCents(original, [wrongApplyForward, wrongApplyOpposite, wrongThinksNoChange, wrongTreatsPctAsPounds]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(original, uniq.slice(0, 4), PCG_fmtMoney);
    const multiplier = e.sign === 1 ? 1 + e.pct / 100 : 1 - e.pct / 100;
    return {
      q,
      options,
      correctIndex,
      hint: 'The final value is the ORIGINAL multiplied by the change multiplier, so divide the final value by that multiplier to reverse it.',
      solution: {
        idea: `Original × ${multiplier} = £${final}, so Original = £${final} ÷ ${multiplier}.`,
        steps: [
          `Multiplier = ${multiplier}`,
          `Original = £${final} ÷ ${multiplier}`,
          `= £${original.toFixed(2)}`,
        ],
        check: `£${original.toFixed(2)} × ${multiplier} = £${final}.`,
      },
    };
  },
};

const s7_successive_percentage_changes = {
  difficulties: [2],
  build(d) {
    const CHANGES = [10, 15, 20, 25, -10, -15, -20, -25, 5, -5, 30, -30];
    const pct1 = pick(CHANGES);
    const pct2 = pick(CHANGES);
    const m1 = 1 + pct1 / 100;
    const m2 = 1 + pct2 / 100;
    const overallMultiplier = m1 * m2;
    const overallPct = (overallMultiplier - 1) * 100;
    const rounded = Math.round(overallPct * 10000) / 10000;
    if (!Number.isFinite(rounded)) return null;
    const sign1 = pct1 >= 0 ? 'increase' : 'decrease';
    const sign2 = pct2 >= 0 ? 'increase' : 'decrease';
    const q = `A price first has a ${Math.abs(pct1)}% ${sign1}, then a ${Math.abs(pct2)}% ${sign2}. What is the overall percentage change?`;
    const fmtChange = (v) => {
      const rv = Math.round(v * 100) / 100;
      if (Math.abs(rv) < 0.005) return 'No overall change';
      const word = rv >= 0 ? 'an increase' : 'a decrease';
      const mag = Math.abs(rv);
      return `${word} of ${mag}%`;
    };
    const wrongAdd = pct1 + pct2;
    const wrongMultiplyPcts = (pct1 * pct2) / 100;
    const wrongFirstOnly = pct1;
    const wrongSecondOnly = pct2;
    const correctStr = fmtChange(rounded);
    const candStrs = [wrongAdd, wrongMultiplyPcts, wrongFirstOnly, wrongSecondOnly]
      .filter((v) => Number.isFinite(v))
      .map(fmtChange);
    const seen = new Set([correctStr]);
    const uniq = [];
    for (const s of candStrs) {
      if (seen.has(s)) continue;
      seen.add(s);
      uniq.push(s);
    }
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMCStr(correctStr, uniq.slice(0, 4));
    return {
      q,
      options,
      correctIndex,
      hint: 'Combine successive percentage changes by MULTIPLYING the two multipliers together, not by adding the percentages.',
      solution: {
        idea: 'Convert each change to a multiplier, multiply them, then convert the combined multiplier back to a percentage change.',
        steps: [
          `Multiplier 1 = 1 ${pct1 >= 0 ? '+' : '−'} ${Math.abs(pct1)}/100 = ${m1}`,
          `Multiplier 2 = 1 ${pct2 >= 0 ? '+' : '−'} ${Math.abs(pct2)}/100 = ${m2}`,
          `Combined multiplier = ${m1} × ${m2} = ${overallMultiplier}`,
          `Overall change = ${correctStr}`,
        ],
        check: `A single change of ${correctStr} has the same effect as the two changes together.`,
      },
    };
  },
};

const s8_simple_vs_compound_comparison = {
  difficulties: [2],
  build(d) {
    const principal = rand(2, 20) * 100;
    const rate = pick([2, 3, 4, 5, 6, 8, 10]);
    const years = rand(2, 4);
    const simpleTotal = principal * rate * years / 100;
    const compoundAmount = principal * Math.pow(1 + rate / 100, years);
    const compoundTotal = compoundAmount - principal;
    const diff = compoundTotal - simpleTotal;
    const roundedDiff = Math.round(diff * 100) / 100;
    if (!Number.isFinite(roundedDiff) || roundedDiff <= 0) return null;
    const q = `£${principal} is invested for ${years} years at ${rate}% per year. How much MORE interest is earned with compound interest than with simple interest?`;
    const wrongZero = 0;
    const wrongDoubleDiff = roundedDiff * 2;
    const wrongCompoundAmount = compoundAmount;
    const wrongSimpleTotal = simpleTotal;
    const uniq = PCG_dedupeByRoundedCents(roundedDiff, [wrongZero, wrongDoubleDiff, wrongCompoundAmount, wrongSimpleTotal]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(roundedDiff, uniq.slice(0, 4), PCG_fmtMoney);
    return {
      q,
      options,
      correctIndex,
      hint: 'Simple interest is the same amount every year; compound interest earns interest on the interest already added. Work out both totals then subtract.',
      solution: {
        idea: 'Compare the total interest earned under each method.',
        steps: [
          `Simple interest total = £${principal} × ${rate}/100 × ${years} = £${simpleTotal.toFixed(2)}`,
          `Compound amount = £${principal} × ${1 + rate / 100}^${years} = £${compoundAmount.toFixed(2)}`,
          `Compound interest total = £${compoundAmount.toFixed(2)} − £${principal} = £${compoundTotal.toFixed(2)}`,
          `Difference = £${compoundTotal.toFixed(2)} − £${simpleTotal.toFixed(2)} = £${roundedDiff.toFixed(2)}`,
        ],
        check: `Compound interest earns £${roundedDiff.toFixed(2)} more than simple interest here.`,
      },
    };
  },
};

const s9_profit_loss_percentage = {
  difficulties: [2],
  build(d) {
    const e = pick(PCG_CHANGE_FRACTIONS);
    const k = rand(2, 15);
    const costPrice = e.den * k;
    const sellingPrice = e.num * k;
    if (costPrice <= 0) return null;
    const isProfit = e.sign === 1;
    const word = isProfit ? 'profit' : 'loss';
    const q = `A trader buys an item for £${costPrice} and sells it for £${sellingPrice}. What is the percentage ${word}, based on the cost price?`;
    const diff = Math.abs(sellingPrice - costPrice);
    const wrongBasedOnSP = Math.round((diff / sellingPrice * 100) * 100) / 100;
    const wrongPoundsOnly = diff;
    const wrongDoublePct = e.pct * 2;
    const wrongHalfPct = e.pct / 2;
    const uniq = PCG_dedupeByRoundedCents(e.pct, [wrongBasedOnSP, wrongPoundsOnly, wrongDoublePct, wrongHalfPct]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(e.pct, uniq.slice(0, 4), (x) => `${x}%`);
    return {
      q,
      options,
      correctIndex,
      hint: 'Percentage profit or loss is always calculated as a percentage of the ORIGINAL cost price, not the selling price.',
      solution: {
        idea: `Percentage ${word} = (difference ÷ cost price) × 100.`,
        steps: [
          `Difference = £${sellingPrice} − £${costPrice} = £${diff}`,
          `Percentage ${word} = (£${diff} ÷ £${costPrice}) × 100`,
          `= ${e.pct}%`,
        ],
        check: `£${costPrice} × ${isProfit ? 1 + e.pct / 100 : 1 - e.pct / 100} = £${sellingPrice}.`,
      },
    };
  },
};

const s10_express_as_percentage_of = {
  difficulties: [2],
  build(d) {
    const pctList = [5, 10, 15, 20, 25, 30, 35, 40, 45, 55, 60, 65, 70, 80, 85, 90];
    const pct = pick(pctList);
    const b = rand(1, 20) * 20;
    const a = b * pct / 100;
    if (!Number.isInteger(a) || a <= 0) return null;
    const q = `In a class of ${b} students, ${a} own a bicycle. What percentage of the class owns a bicycle?`;
    const wrongFlipped = Math.round((b / a) * 100 * 100) / 100;
    const wrongDoublePct = pct * 2;
    const wrongHalfPct = pct / 2;
    const wrongDiffAsPct = b - a;
    const uniq = PCG_dedupeByRoundedCents(pct, [wrongFlipped, wrongDoublePct, wrongHalfPct, wrongDiffAsPct]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(pct, uniq.slice(0, 4), (x) => `${x}%`);
    return {
      q,
      options,
      correctIndex,
      hint: 'Write it as a fraction (part ÷ whole) then multiply by 100 to get a percentage.',
      solution: {
        idea: 'Percentage = (part ÷ whole) × 100.',
        steps: [
          `${a} ÷ ${b} = ${a / b}`,
          `${a / b} × 100 = ${pct}%`,
        ],
        check: `${pct}% of ${b} is ${a}.`,
      },
    };
  },
};

