const s11_find_growth_rate = {
  difficulties: [3],
  build(d) {
    const e = pick(PCG_RATE_TABLE);
    const k = rand(1, 6);
    const P = e.den * k;
    const A = e.num * k;
    if (P <= 0 || A <= 0) return null;
    const word = e.sign === 1 ? 'growth' : 'depreciation';
    const q = `An investment of £${P} changes to £${A} after ${e.n} years of fixed-rate compound ${word}. What is the annual rate?`;
    const totalMultiplier = A / P;
    const totalPctChange = e.sign === 1 ? (totalMultiplier - 1) * 100 : (1 - totalMultiplier) * 100;
    const wrongLinear = Math.round((totalPctChange / e.n) * 100) / 100;
    const wrongTotal = Math.round(totalPctChange * 100) / 100;
    const wrongPlus5 = e.r + 5;
    const wrongMinus5 = e.r - 5 > 0 ? e.r - 5 : e.r + 10;
    const uniq = PCG_dedupeByRoundedCents(e.r, [wrongLinear, wrongTotal, wrongPlus5, wrongMinus5]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(e.r, uniq.slice(0, 4), (x) => `${x}%`);
    return {
      q,
      options,
      correctIndex,
      hint: 'Find the OVERALL multiplier (final ÷ initial), then take the nth root (n = number of years) to get the annual multiplier.',
      solution: {
        idea: `Annual multiplier = (final ÷ initial)^(1/years).`,
        steps: [
          `Overall multiplier = £${A} ÷ £${P} = ${totalMultiplier}`,
          `Annual multiplier = ${totalMultiplier}^(1/${e.n}) = ${e.sign === 1 ? 1 + e.r / 100 : 1 - e.r / 100}`,
          `Annual rate = ${e.r}%`,
        ],
        check: `£${P} × ${e.sign === 1 ? 1 + e.r / 100 : 1 - e.r / 100}^${e.n} = £${A}.`,
      },
    };
  },
};

const s12_reverse_percentage_two_changes = {
  difficulties: [3],
  build(d) {
    const e1 = pick(PCG_CHANGE_FRACTIONS);
    const e2 = pick(PCG_CHANGE_FRACTIONS);
    const k = rand(2, 12);
    const original = e1.den * e2.den * k;
    const final = e1.num * e2.num * k;
    if (original <= 0 || final <= 0) return null;
    if (original > 100000 || final > 100000) return null;
    const dir1 = e1.sign === 1 ? 'increased' : 'decreased';
    const dir2 = e2.sign === 1 ? 'increased' : 'decreased';
    const q = `A price is first ${dir1} by ${e1.pct}%, then the new price is ${dir2} by ${e2.pct}%. The final price is £${final}. What was the original price?`;
    const m1 = e1.num / e1.den;
    const m2 = e2.num / e2.den;
    const combinedMultiplier = m1 * m2;
    const wrongOneStepOnly = final / m1;
    const wrongOtherStepOnly = final / m2;
    const wrongAppliesForward = final * combinedMultiplier;
    const wrongIsFinal = final;
    const uniq = PCG_dedupeByRoundedCents(original, [wrongOneStepOnly, wrongOtherStepOnly, wrongAppliesForward, wrongIsFinal]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(original, uniq.slice(0, 4), PCG_fmtMoney);
    return {
      q,
      options,
      correctIndex,
      hint: 'Combine both changes into one overall multiplier first, then divide the final value by that combined multiplier.',
      solution: {
        idea: 'Original × (multiplier 1 × multiplier 2) = final value.',
        steps: [
          `Multiplier 1 = ${m1}, Multiplier 2 = ${m2}`,
          `Combined multiplier = ${combinedMultiplier}`,
          `Original = £${final} ÷ ${combinedMultiplier}`,
          `= £${original.toFixed(2)}`,
        ],
        check: `£${original.toFixed(2)} × ${combinedMultiplier} = £${final}.`,
      },
    };
  },
};

const s13_net_effect_same_pct = {
  difficulties: [3],
  build(d) {
    const xList = [4, 5, 8, 10, 12, 15, 20, 25, 30, 40, 50, 60];
    const x = pick(xList);
    const netMultiplier = (1 + x / 100) * (1 - x / 100);
    const netPctChange = (netMultiplier - 1) * 100;
    const magnitude = Math.abs(netPctChange);
    const roundedMag = Math.round(magnitude * 10000) / 10000;
    if (!Number.isFinite(roundedMag) || roundedMag <= 0) return null;
    const fmtNum = (v) => (Number.isInteger(v) ? String(v) : String(Math.round(v * 10000) / 10000));
    const correctStr = `A decrease of ${fmtNum(roundedMag)}%`;
    const q = `A quantity increases by ${x}%, then decreases by ${x}%. What is the overall effect?`;
    const distractorStrs = [
      'No overall change',
      `An increase of ${fmtNum(roundedMag)}%`,
      `A decrease of ${fmtNum(x * 2)}%`,
      `A decrease of ${fmtNum(x)}%`,
    ];
    const seen = new Set([correctStr]);
    const uniq = [];
    for (const s of distractorStrs) {
      if (seen.has(s)) continue;
      seen.add(s);
      uniq.push(s);
    }
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMCStr(correctStr, uniq.slice(0, 4));
    return {
      q,
      options,
      correctIndex,
      hint: 'Combine the two changes as a single multiplier: (1 + x/100)(1 − x/100). Multiply out to see the net effect.',
      solution: {
        idea: 'Increasing then decreasing by the same percentage does NOT cancel out, because the second change applies to a different (larger) amount.',
        steps: [
          `Multiplier = (1 + ${x}/100)(1 − ${x}/100) = 1 − (${x}/100)²`,
          `= 1 − ${(x / 100) * (x / 100)}`,
          `= ${netMultiplier}`,
          `Overall effect: ${correctStr}`,
        ],
        check: `The net multiplier ${netMultiplier} is always slightly less than 1, so the overall effect is always a decrease.`,
      },
    };
  },
};

const s14_non_annual_compounding = {
  difficulties: [3],
  build(d) {
    const e = pick(PCG_NONANNUAL_TABLE);
    const years = rand(1, 2);
    const periods = e.freq * years;
    if (periods > 30) return null;
    const principal = rand(2, 10) * 100;
    const amount = principal * Math.pow(1 + e.periodicRate / 100, periods);
    const rounded = Math.round(amount * 100) / 100;
    if (!Number.isFinite(rounded)) return null;
    const q = `£${principal} is invested at ${e.annualRate}% per year, compounded ${e.label}, for ${years} year${years > 1 ? 's' : ''}. What is the value of the investment at the end? (${e.freq} ${e.label} periods per year)`;
    const wrongUsesAnnualDirectly = principal * Math.pow(1 + e.annualRate / 100, years);
    const wrongUsesAnnualRatePerPeriod = principal * Math.pow(1 + e.annualRate / 100, periods);
    const wrongLinear = principal + principal * e.annualRate * years / 100;
    const wrongWrongPeriods = principal * Math.pow(1 + e.periodicRate / 100, years);
    const uniq = PCG_dedupeByRoundedCents(rounded, [wrongUsesAnnualDirectly, wrongUsesAnnualRatePerPeriod, wrongLinear, wrongWrongPeriods]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(rounded, uniq.slice(0, 4), PCG_fmtMoney);
    return {
      q,
      options,
      correctIndex,
      hint: `Divide the annual rate by the number of periods per year to get the periodic rate, and multiply the years by the number of periods per year to get the total number of periods.`,
      solution: {
        idea: `Periodic rate = ${e.annualRate}% ÷ ${e.freq} = ${e.periodicRate}%. Number of periods = ${e.freq} × ${years} = ${periods}.`,
        steps: [
          `Periodic rate = ${e.annualRate}/${e.freq} = ${e.periodicRate}%`,
          `Number of periods = ${e.freq} × ${years} = ${periods}`,
          `Amount = £${principal} × ${1 + e.periodicRate / 100}^${periods}`,
          `= £${rounded.toFixed(2)}`,
        ],
        check: `£${rounded.toFixed(2)} is the value after ${periods} ${e.label} periods.`,
      },
    };
  },
};

const s15_compare_two_investments = {
  difficulties: [3],
  build(d) {
    const mkScenario = () => ({ P: rand(2, 10) * 100, r: pick([2, 3, 4, 5, 6, 8, 10, 12]), n: rand(2, 5) });
    const A1 = mkScenario();
    const A2 = mkScenario();
    const amt1 = A1.P * Math.pow(1 + A1.r / 100, A1.n);
    const amt2 = A2.P * Math.pow(1 + A2.r / 100, A2.n);
    const diff = Math.abs(amt1 - amt2);
    const roundedDiff = Math.round(diff * 100) / 100;
    if (!Number.isFinite(roundedDiff) || roundedDiff < 1) return null;
    const q = `Investment A: £${A1.P} at ${A1.r}% compound interest per year for ${A1.n} years. Investment B: £${A2.P} at ${A2.r}% compound interest per year for ${A2.n} years. What is the difference between the two final amounts, to the nearest penny?`;
    const simple1 = A1.P + A1.P * A1.r * A1.n / 100;
    const simple2 = A2.P + A2.P * A2.r * A2.n / 100;
    const wrongUsesSimple = Math.abs(simple1 - simple2);
    const wrongPrincipalDiff = Math.abs(A1.P - A2.P);
    const wrongHalfDiff = roundedDiff / 2;
    const wrongDoubleDiff = roundedDiff * 2;
    const uniq = PCG_dedupeByRoundedCents(roundedDiff, [wrongUsesSimple, wrongPrincipalDiff, wrongHalfDiff, wrongDoubleDiff]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(roundedDiff, uniq.slice(0, 4), PCG_fmtMoney);
    return {
      q,
      options,
      correctIndex,
      hint: 'Work out each final amount separately using the compound growth formula, then subtract.',
      solution: {
        idea: 'Calculate both final amounts, then find the (positive) difference between them.',
        steps: [
          `Investment A: £${A1.P} × ${1 + A1.r / 100}^${A1.n} = £${amt1.toFixed(2)}`,
          `Investment B: £${A2.P} × ${1 + A2.r / 100}^${A2.n} = £${amt2.toFixed(2)}`,
          `Difference = £${roundedDiff.toFixed(2)}`,
        ],
        check: `The two final amounts differ by £${roundedDiff.toFixed(2)}.`,
      },
    };
  },
};

