const s16_years_to_exceed_target = {
  difficulties: [4],
  build(d) {
    const principal = rand(2, 10) * 100;
    const rate = pick([3, 4, 5, 6, 8, 10, 12, 15]);
    const multiplier = 1 + rate / 100;
    const targetMultiple = pick([1.3, 1.5, 1.75, 2, 2.5, 3]);
    const target = Math.round(principal * targetMultiple / 10) * 10;
    if (target <= principal) return null;
    let years = 0;
    let amount = principal;
    const MAX_YEARS = 60;
    while (amount <= target && years < MAX_YEARS) {
      amount *= multiplier;
      years++;
    }
    if (years >= MAX_YEARS || years < 1) return null;
    const q = `£${principal} is invested at ${rate}% compound interest per year. After how many whole years will the investment FIRST be worth more than £${target}?`;
    const wrongOneLess = years - 1;
    const wrongOneMore = years + 1;
    const wrongLinearEstimate = Math.ceil(((target / principal - 1) * 100) / rate);
    const wrongTwoLess = years - 2;
    const candidates = [wrongOneLess, wrongOneMore, wrongLinearEstimate, wrongTwoLess].filter((v) => Number.isInteger(v) && v >= 1);
    const uniq = PCG_dedupeByRoundedCents(years, candidates);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(years, uniq.slice(0, 4), (x) => `${x} years`);
    return {
      q,
      options,
      correctIndex,
      hint: 'Multiply repeatedly by the multiplier, one year at a time, and count how many years it takes to first go past the target.',
      solution: {
        idea: 'Apply the multiplier year by year and check after each year.',
        steps: [
          `Multiplier = ${multiplier}`,
          `After ${years - 1} year${years - 1 === 1 ? '' : 's'}, the amount is not yet above £${target}`,
          `After ${years} years, £${principal} × ${multiplier}^${years} ≈ £${Math.round(amount * 100) / 100}, which is above £${target}`,
        ],
        check: `${years} whole years are needed.`,
      },
    };
  },
};

const s17_rate_between_two_wholes = {
  difficulties: [4],
  build(d) {
    const principal = rand(3, 9) * 1000;
    const years = rand(2, 3);
    const wholeRate = pick([4, 6, 7, 9, 11, 13, 14, 17, 18]);
    const frac = rand(20, 80) / 100;
    const trueRate = wholeRate + frac;
    const amount = principal * Math.pow(1 + trueRate / 100, years);
    const roundedAmount = Math.round(amount);
    const lowAmount = principal * Math.pow(1 + wholeRate / 100, years);
    const highAmount = principal * Math.pow(1 + (wholeRate + 1) / 100, years);
    if (!(lowAmount < roundedAmount && roundedAmount < highAmount)) return null;
    const q = `£${principal} is invested for ${years} years at a fixed annual compound interest rate. The investment grows to £${roundedAmount}. Between which two consecutive whole-number percentages does the annual rate lie?`;
    const correctStr = `${wholeRate}% and ${wholeRate + 1}%`;
    const distractorStrs = [
      `${wholeRate - 1}% and ${wholeRate}%`,
      `${wholeRate + 1}% and ${wholeRate + 2}%`,
      `${wholeRate - 2}% and ${wholeRate - 1}%`,
      `${wholeRate + 2}% and ${wholeRate + 3}%`,
    ];
    const seen = new Set([correctStr]);
    const uniq = [];
    for (const s of distractorStrs) {
      if (seen.has(s)) continue;
      seen.add(s);
      uniq.push(s);
    }
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMCStr(correctStr, uniq.slice(0, 4));
    return {
      q,
      options,
      correctIndex,
      hint: 'Try whole-number rates either side and see which pair brackets the given final amount (trial and improvement).',
      solution: {
        idea: 'Test consecutive whole-number rates and see between which two the final amount falls.',
        steps: [
          `At ${wholeRate}%: £${principal} × ${1 + wholeRate / 100}^${years} ≈ £${Math.round(lowAmount)}`,
          `At ${wholeRate + 1}%: £${principal} × ${1 + (wholeRate + 1) / 100}^${years} ≈ £${Math.round(highAmount)}`,
          `£${roundedAmount} lies between these, so the rate is between ${wholeRate}% and ${wholeRate + 1}%`,
        ],
        check: `${wholeRate}% gives too little and ${wholeRate + 1}% gives too much.`,
      },
    };
  },
};

const s18_multistep_population_percentage = {
  difficulties: [4],
  build(d) {
    const population = rand(5, 50) * 1000;
    const rate = pick([2, 3, 4, 5, 6, 8, 10]);
    const years = rand(2, 4);
    const newPopRaw = population * Math.pow(1 + rate / 100, years);
    const newPop = Math.round(newPopRaw);
    const pctAsked = pick([10, 15, 20, 25, 30, 40, 60]);
    const answer = Math.round(newPop * pctAsked / 100);
    if (!Number.isFinite(answer) || answer <= 0) return null;
    const q = `The population of a town is ${population}. It grows by ${rate}% per year for ${years} years. After that growth, what is ${pctAsked}% of the new population (to the nearest whole person)?`;
    const wrongUsesOriginalPop = Math.round(population * pctAsked / 100);
    const wrongDoublePct = Math.round(newPop * pctAsked * 2 / 100);
    const wrongUsesGrowthOnly = Math.round((newPop - population) * pctAsked / 100);
    const wrongUsesComplement = Math.round(newPop * (100 - pctAsked) / 100);
    const uniq = PCG_dedupeByRoundedCents(answer, [wrongUsesOriginalPop, wrongDoublePct, wrongUsesGrowthOnly, wrongUsesComplement]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(answer, uniq.slice(0, 4), (x) => `${Math.round(x)} people`);
    return {
      q,
      options,
      correctIndex,
      hint: 'First find the new (grown) population using the compound growth multiplier, THEN take the percentage of that new figure.',
      solution: {
        idea: 'This is a two-step problem: grow the population first, then find a percentage of the result.',
        steps: [
          `New population = ${population} × ${1 + rate / 100}^${years} ≈ ${newPop}`,
          `${pctAsked}% of ${newPop} = ${newPop} × ${pctAsked}/100`,
          `≈ ${answer} people`,
        ],
        check: `${answer} people is ${pctAsked}% of the grown population of ${newPop}.`,
      },
    };
  },
};

const s19_reverse_engineer_periods = {
  difficulties: [4],
  build(d) {
    const principal = rand(2, 10) * 100;
    const rate = pick([5, 8, 10, 12, 15, 20]);
    const trueYears = rand(2, 6);
    const amount = principal * Math.pow(1 + rate / 100, trueYears);
    const roundedAmount = Math.round(amount * 100) / 100;
    const q = `£${principal} is invested at ${rate}% compound interest per year. After how many whole years does it first reach exactly £${roundedAmount.toFixed(2)} (to the nearest penny)?`;
    let foundYears = null;
    const TOL = 0.005 * roundedAmount + 0.02;
    for (let n = 1; n <= 30; n++) {
      const a = principal * Math.pow(1 + rate / 100, n);
      if (Math.abs(a - roundedAmount) < TOL) { foundYears = n; break; }
    }
    if (foundYears !== trueYears) return null;
    const wrongOneLess = trueYears - 1;
    const wrongOneMore = trueYears + 1;
    const wrongTwoMore = trueYears + 2;
    const wrongDoubled = trueYears * 2;
    const candidates = [wrongOneLess, wrongOneMore, wrongTwoMore, wrongDoubled].filter((v) => Number.isInteger(v) && v >= 1);
    const uniq = PCG_dedupeByRoundedCents(trueYears, candidates);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(trueYears, uniq.slice(0, 4), (x) => `${x} years`);
    return {
      q,
      options,
      correctIndex,
      hint: 'Try successive whole numbers of years, calculating the amount each time, until it matches the target value.',
      solution: {
        idea: 'Test n = 1, 2, 3, … in the compound growth formula until the amount matches.',
        steps: [
          `Multiplier = ${1 + rate / 100}`,
          `£${principal} × ${1 + rate / 100}^${trueYears} = £${roundedAmount.toFixed(2)}`,
        ],
        check: `${trueYears} years gives exactly £${roundedAmount.toFixed(2)}.`,
      },
    };
  },
};

const s20_depreciation_to_fraction_target = {
  difficulties: [4],
  build(d) {
    const originalValue = rand(2, 20) * 1000;
    const rate = pick([10, 12, 15, 18, 20, 25]);
    const multiplier = 1 - rate / 100;
    const fr = pick(PCG_FRACTION_TARGETS);
    const target = originalValue * fr.num / fr.den;
    let years = 0;
    let value = originalValue;
    const MAX_YEARS = 60;
    while (value >= target && years < MAX_YEARS) {
      value *= multiplier;
      years++;
    }
    if (years >= MAX_YEARS || years < 1) return null;
    const roundedTarget = Math.round(target * 100) / 100;
    const q = `A car is bought for £${originalValue}. It depreciates by ${rate}% per year. After how many whole years does its value FIRST drop below ${fr.label} of its original price (£${roundedTarget})?`;
    const wrongOneLess = years - 1;
    const wrongOneMore = years + 1;
    const wrongLinearEstimate = Math.ceil(((1 - fr.num / fr.den) * 100) / rate);
    const wrongTwoMore = years + 2;
    const candidates = [wrongOneLess, wrongOneMore, wrongLinearEstimate, wrongTwoMore].filter((v) => Number.isInteger(v) && v >= 1);
    const uniq = PCG_dedupeByRoundedCents(years, candidates);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(years, uniq.slice(0, 4), (x) => `${x} years`);
    return {
      q,
      options,
      correctIndex,
      hint: 'Work out the target value first (the fraction of the original price), then apply the depreciation multiplier year by year until the value first drops below it.',
      solution: {
        idea: `Target value = £${originalValue} × ${fr.num}/${fr.den} = £${roundedTarget}.`,
        steps: [
          `Multiplier per year = 1 − ${rate}/100 = ${multiplier}`,
          `Apply the multiplier repeatedly until the value drops below £${roundedTarget}`,
          `This first happens after ${years} years`,
        ],
        check: `${years} whole years are needed for the value to drop below £${roundedTarget}.`,
      },
    };
  },
};

// ---------------------------------------------------------------------------
// Growth and decay as a distinct idea from money (population, substance mass,
// half-life), using the same compound-multiplier method but a non-monetary
// vocabulary the audit found genuinely missing: growth/decay factor, half-life.
// ---------------------------------------------------------------------------
const s21_exponential_growth_population = {
  difficulties: [1, 2],
  build(d) {
    const population = pick([200, 500, 800, 1000, 1500, 2000]);
    const rate = pick([5, 10, 15, 20]);
    const years = rand(2, 3);
    const growthFactor = 1 + rate / 100;
    const newPop = Math.round(population * Math.pow(growthFactor, years));
    const wrongLinear = Math.round(population * (1 + (rate * years) / 100));
    const wrongOneYear = Math.round(population * growthFactor);
    const wrongExtraYear = Math.round(population * Math.pow(growthFactor, years + 1));
    const wrongDecayed = Math.round(population * Math.pow(1 - rate / 100, years));
    const uniq = PCG_dedupeByRoundedCents(newPop, [wrongLinear, wrongOneYear, wrongExtraYear, wrongDecayed]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(newPop, uniq.slice(0, 4), (x) => `${Math.round(x)}`);
    return {
      q: `A population of ${population} bacteria grows by ${rate}% every hour. What is the population after ${years} hours?`,
      options, correctIndex,
      hint: `Multiply by the growth factor (1 + rate/100) once for every hour, exactly as with compound interest, just applied to a population instead of money.`,
      solution: {
        idea: `Growing by a fixed percentage each period, repeated, uses the same compound-multiplier idea as compound interest: multiply by the growth factor once per period.`,
        steps: [`Growth factor = 1 + ${rate}/100 = ${growthFactor}.`, `New population = ${population} × ${growthFactor}^${years} ≈ ${newPop}.`],
        check: `Check year by year: ${Array.from({ length: years }, (_, i) => Math.round(population * Math.pow(growthFactor, i + 1))).join(" → ")}.`,
      },
    };
  },
};
const s22_exponential_decay_substance = {
  difficulties: [1, 2],
  build(d) {
    const amount = pick([200, 400, 500, 800, 1000]);
    const rate = pick([5, 10, 15, 20]);
    const periods = rand(2, 3);
    const decayFactor = 1 - rate / 100;
    const newAmount = Math.round(amount * Math.pow(decayFactor, periods) * 100) / 100;
    const wrongLinear = Math.round(amount * (1 - (rate * periods) / 100) * 100) / 100;
    const wrongOnePeriod = Math.round(amount * decayFactor * 100) / 100;
    const wrongGrowth = Math.round(amount * Math.pow(1 + rate / 100, periods) * 100) / 100;
    const wrongExtraPeriod = Math.round(amount * Math.pow(decayFactor, periods + 1) * 100) / 100;
    const uniq = PCG_dedupeByRoundedCents(newAmount, [wrongLinear, wrongOnePeriod, wrongGrowth, wrongExtraPeriod]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(newAmount, uniq.slice(0, 4), (x) => Number(x).toFixed(2));
    return {
      q: `A radioactive substance has a mass of ${amount}g. It decays by ${rate}% every day. What mass remains after ${periods} days?`,
      options, correctIndex,
      hint: `Multiply by the decay factor (1 - rate/100) once for every day, exactly the reverse of growth.`,
      solution: {
        idea: `Decaying by a fixed percentage each period, repeated, uses the same compound-multiplier idea as depreciation: multiply by the decay factor once per period.`,
        steps: [`Decay factor = 1 - ${rate}/100 = ${decayFactor}.`, `Remaining mass = ${amount} × ${decayFactor}^${periods} ≈ ${newAmount}g.`],
      },
    };
  },
};
const s23_half_life_remaining = {
  difficulties: [3, 4],
  build(d) {
    const initial = pick([64, 128, 256, 512, 1024, 2048]);
    const halfLives = rand(2, 5);
    const remaining = initial / Math.pow(2, halfLives);
    if (!Number.isInteger(remaining)) return null;
    const wrongDivideByHalfLives = Math.round((initial / halfLives) * 100) / 100;
    const wrongOneExtra = initial / Math.pow(2, halfLives + 1);
    const wrongOneFewer = initial / Math.pow(2, halfLives - 1);
    const wrongMultipliedInstead = initial * Math.pow(2, halfLives);
    const wrongAmountLost = initial - remaining;
    const uniq = PCG_dedupeByRoundedCents(remaining, [wrongDivideByHalfLives, wrongOneExtra, wrongOneFewer, wrongMultipliedInstead, wrongAmountLost].filter((v) => v > 0));
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(remaining, uniq.slice(0, 4));
    return {
      q: `A sample of ${initial}g of a radioactive isotope has a fixed half-life. After ${halfLives} half-lives, how much of the original sample remains?`,
      options, correctIndex,
      hint: `Each half-life halves whatever amount is currently left, so after n half-lives, the remaining amount is the original divided by 2ⁿ.`,
      solution: {
        idea: `A half-life is the time it takes for exactly half of whatever is currently present to decay, so repeated half-lives repeatedly halve the remaining amount: an exponential decay with a decay factor of exactly ½ each time.`,
        steps: [`After each half-life, halve the previous amount: ${Array.from({ length: halfLives }, (_, i) => initial / Math.pow(2, i + 1)).join(" → ")}.`, `After ${halfLives} half-lives: ${initial} ÷ 2^${halfLives} = ${remaining}g.`],
      },
    };
  },
};
const s24_periods_to_threshold = {
  difficulties: [4],
  build(d) {
    const initial = pick([1000, 2000, 4000, 5000]);
    const rate = pick([10, 15, 20, 25, 30, 50]);
    const decayFactor = 1 - rate / 100;
    const threshold = initial / 2;
    let n = 0, amt = initial;
    while (amt >= threshold && n < 15) { amt *= decayFactor; n++; }
    if (n === 0 || n > 12) return null;
    const wrongOneFewer = n - 1 > 0 ? n - 1 : n + 1;
    const wrongOneMore = n + 1;
    const wrongDouble = n * 2;
    const uniq = PCG_dedupeByRoundedCents(n, [wrongOneFewer, wrongOneMore, wrongDouble, n + 2]);
    if (uniq.length < 4) return null;
    const { options, correctIndex } = buildMC(n, uniq.slice(0, 4));
    return {
      q: `A population of ${initial} decreases by ${rate}% each year. After how many whole years does the population first fall below half its original size?`,
      options, correctIndex,
      hint: `Multiply repeatedly by the decay factor, year by year, and count how many multiplications it takes to drop below half.`,
      solution: {
        idea: `With no simple one-step formula for the exact year, check year by year until the population first drops below half its starting value.`,
        steps: Array.from({ length: n }, (_, i) => `After year ${i + 1}: ${initial} × ${decayFactor}^${i + 1} ≈ ${Math.round(initial * Math.pow(decayFactor, i + 1))}.`),
        check: `Half of ${initial} is ${threshold}; after year ${n} the population (≈${Math.round(initial * Math.pow(decayFactor, n))}) has dropped below that, while after year ${n - 1} it had not yet.`,
      },
    };
  },
};

