          steps: [`k = ${m1} ÷ ${L1}³ = ${m1} ÷ ${L1 * L1 * L1} = ${k}`, `mass = ${k} × ${L2}³ = ${k} × ${L2 * L2 * L2} = ${correct}`],
          check: `Check: ${k} × ${L1 * L1 * L1} = ${m1} ✓`,
