      const { options, correctIndex } = buildMC(baseAngle, decoys, deg);
      return {
        q: `PT and PU are both tangents to the circle from an external point P, touching the circle at T and U. Angle TPU = ${angP}°. Find angle PTU (marked "?").`,
        options, correctIndex, svg,
        hint: `Two tangents drawn from the same external point are always equal in length, making triangle PTU isosceles. Use that with the triangle angle sum.`,
        solution: {
          scenario: `PT and PU are tangents from the same external point P, so PT = PU (two tangents from one point are always equal in length). Angle TPU = ${angP}°.`,
          idea: `Since PT = PU, triangle PTU is isosceles, so its base angles at T and U are equal. The triangle angle sum then shares out what remains after the apex angle.`,
          method: ["Subtract the apex angle from 180°.", "Halve the result, since the base angles are equal."],
          steps: [`Subtract the apex from 180°: 180° − ${angP}° = ${180 - angP}°.`, `Halve it, since angle PTU = angle PUT: ${180 - angP}° ÷ 2 = ${baseAngle}°.`],
          check: `Check: ${angP}° + ${baseAngle}° + ${baseAngle}° = ${angP + baseAngle * 2}°.`,
        },
      };
