      const { options, correctIndex } = buildMC(dist, decoys);
      const svg = cgGridSvg(SL(CG_ox + x1 * CG_S, CG_oy - y1 * CG_S, CG_ox + x2 * CG_S, CG_oy - y2 * CG_S, "#7c5cff", 2.5) + cgDot(x1, y1, `A(${x1}, ${y1})`) + cgDot(x2, y2, `B(${x2}, ${y2})`, "#22c8b8"));
      return { q: `Find the distance AB.`, options, correctIndex, svg,
        hint: `Form a right-angled triangle from the horizontal and vertical gaps, then use Pythagoras' theorem.`,
        solution: { idea: `Distance = √((x2−x1)² + (y2−y1)²), which is Pythagoras' theorem applied to the horizontal and vertical gaps.`, steps: [`Horizontal gap: ${dx}. Vertical gap: ${dy}.`, `Distance = √(${dx}² + ${dy}²) = √${dx * dx + dy * dy} = ${dist}.`], check: `Check: ${dist}² = ${dist * dist} = ${dx}² + ${dy}².` },
      };
